import{_ as a,o as i,c as t,a6 as l}from"./chunks/framework.DL_pga9_.js";const u=JSON.parse('{"title":"Generalized = delete Declarations","description":"","frontmatter":{},"headers":[],"relativePath":"design/archive/generalized_delete.md","filePath":"design/archive/generalized_delete.md","lastUpdated":1780030916000}'),n={name:"design/archive/generalized_delete.md"};function r(d,e,s,o,c,p){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="generalized-delete-declarations" tabindex="-1">Generalized <code>= delete</code> Declarations <a class="header-anchor" href="#generalized-delete-declarations" aria-label="Permalink to “Generalized = delete Declarations”">​</a></h1><h2 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to “Order”">​</a></h2><p>Recommended Issue order: 2.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Extend the current <code>= delete</code> support from type-specialization-only usage into a general negative declaration mechanism.</p><p>Current support can reject cases such as:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type&lt;T&gt; ref&lt;ref&lt;T&gt;&gt; = delete;</span></span></code></pre></div><p>This design should define and implement where deleted declarations are legal, how they participate in overload and specialization resolution, and how diagnostics should point to the deleted declaration.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><p>Prerequisites:</p><ul><li>Existing type alias specialization and overload/specialization resolution.</li></ul><p>Unblocks:</p><ul><li><a href="./../enhanced_tuples">Enhanced Tuple Types</a>, for deleted fallback projections such as invalid <code>tuple_element</code>.</li><li><a href="./../auto_derive_traits">Auto Traits And Derive Traits</a>, for negative or blocked auto-trait behavior.</li><li>Future constraint modeling that needs &quot;matched but forbidden&quot; diagnostics.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>In scope:</p><ul><li>Deleted type aliases and type specializations.</li><li>Deleted function overloads or generic function specializations.</li><li>Deleted const specializations if useful for constraint modeling.</li><li>Resolution rule: deleted candidates may match, but selecting one is a compile-time error.</li><li>Clear diagnostics showing the deleted declaration that matched.</li></ul><p>Out of scope:</p><ul><li>Runtime behavior.</li><li>Trait auto-derive interaction.</li><li><code>const fun</code> execution.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to “Acceptance Criteria”">​</a></h2><ul><li><code>type&lt;T&gt; X&lt;Bad&lt;T&gt;&gt; = delete;</code> rejects matching type use.</li><li><code>fun&lt;T&gt; foo(value: Bad&lt;T&gt;) = delete;</code> rejects matching calls.</li><li>A more specific deleted declaration beats a more general valid declaration.</li><li>Non-matching deleted declarations do not affect valid overloads.</li><li>Parser/typechecker tests cover exact match, generic pattern match, and fallback behavior.</li></ul><h2 id="implementation-status" tabindex="-1">Implementation Status <a class="header-anchor" href="#implementation-status" aria-label="Permalink to “Implementation Status”">​</a></h2><p>Implemented:</p><ul><li>Deleted primary and specialized type aliases.</li><li>Deleted generic function overloads selected by argument type patterns.</li><li>Deleted non-generic functions as forbidden callable signatures.</li><li>Deleted const predicate specializations.</li><li>Candidate selection treats deleted declarations as normal candidates first; selecting one is a compile-time error.</li><li>More-specific deleted generic function patterns beat less-specific valid fallbacks.</li><li>Parser and typechecker tests cover exact matches, generic pattern matches, fallback behavior, and const predicates.</li></ul><p>Current limitations:</p><ul><li>Function overload selection is intentionally narrow and only models same-name generic candidates needed by deleted declarations.</li><li>Runtime backends skip deleted functions; deleted declarations are expected to be rejected by type checking before execution.</li></ul>',25)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
